function actNorm(value){return String(value).trim().replace(/[−–]/g,'-').replace(/\s+/g,' ').toLocaleLowerCase();}
function actWord(value){return String(value).normalize('NFC').toLocaleUpperCase().replace(/[^\p{L}]/gu,'');}
function activityImage(value){if(value===undefined||value==='')return '';if(typeof value!=='string'||value.length>300000||!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(value))throw Error('Use a PNG, JPEG or WebP image uploaded through the editor.');return value;}
function activityItemFields(format,item,i){if(!ACTIVITIES[format])return {};const c=ACTIVITIES[format],extra=GEO_FORMATS[format]?geoFields(item):format==='picturevocab'?vocabFields(item):{};if(c.input==='word'&&(!/^\p{L}{2,14}$/u.test(item.answer.trim())))throw Error(`Word ${i+1}: use 2–14 letters, without spaces or punctuation.`);if(c.input==='boolean'&&!['true','false'].includes(actNorm(item.answer)))throw Error('True or False answers must be True or False.');if(c.input==='order'&&(item.answer.split('|').length<2||item.answer.split('|').length>12||item.answer.split('|').some(v=>!v.trim())))throw Error('Use 2–12 words or entries, separated by |.');if(['choice','image'].includes(c.input)&&(!item.options.length||item.options.length>3))throw Error('Add 1–3 wrong choices for each question.');if(c.input==='diagram'){const p=item.point;if(!p||!Number.isFinite(p.x)||!Number.isFinite(p.y)||p.x<0||p.x>100||p.y<0||p.y>100)throw Error(`Place marker ${i+1} on the diagram.`);extra.point={x:p.x,y:p.y};}if(item.image)extra.image=activityImage(item.image);if(item.visual==='rectangle'){extra.visual='rectangle';extra.width=Number(item.width);extra.height=Number(item.height);if(!Number.isFinite(extra.width)||!Number.isFinite(extra.height)||extra.width<=0||extra.height<=0)throw Error('Diagram dimensions must be positive numbers.');}return extra;}
function validateActivityLesson(raw,items){const c=ACTIVITIES[raw.format];if(!c)return;validateTemplate(raw,items);validatePrimary(raw,items);labValidate(raw,items);if(raw.format==='picturevocab')vocabValidate(items);if(['wordsearch','crossword'].includes(raw.format)&&items.length>12)throw Error('Use up to 12 words in a word puzzle.');if(['wordsearch','crossword','memory'].includes(raw.format)&&new Set(items.map(q=>actNorm(q.answer))).size!==items.length)throw Error('Use a different answer for every word or memory card.');if(raw.format==='diagram'&&items.length>12)throw Error('Use up to 12 diagram labels.');if(raw.format==='imagequiz'&&items.some(q=>!q.image&&!q.visual))throw Error('Upload a picture for every image question.');if(JSON.stringify(raw).length>5000000)throw Error('This lesson is too large. Use fewer or smaller images.');}
function activitySettings(raw){const s=raw||{},result={diagramImage:activityImage(s.diagramImage),cellDifficulty:s.cellDifficulty??'easy',cellType:s.cellType??'animal',generatorCount:s.generatorCount??10,generatorMax:s.generatorMax??20,generatorOperation:s.generatorOperation??'mixed'};if(!['animal','plant'].includes(result.cellType))throw Error('Choose Animal or Plant for Cell Structures.');if(!Object.hasOwn(CELL_LEVELS,result.cellDifficulty))throw Error('Choose Easy, Medium or Hard for the cell diagram.');if(!Number.isInteger(result.generatorCount)||result.generatorCount<2||result.generatorCount>40||!Number.isInteger(result.generatorMax)||result.generatorMax<2||result.generatorMax>100||!['mixed','+','-','×','÷'].includes(result.generatorOperation))throw Error('Maths Generator needs 2–40 questions, a maximum number of 2–100, and a supported operation.');return result;}
